{
  "name": "@fnnm/opencode-dynamic-workflows",
  "version": "1.0.4",
  "private": false,
  "description": "Claude-Code-style dynamic workflow orchestration for OpenCode.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist/",
    "src/",
    "README.md"
  ],
  "scripts": {
    "test": "bun test",
    "check": "tsc --noEmit",
    "format": "biome format --write .",
    "lint": "biome lint .",
    "build": "bun build src/index.ts --outdir dist --target node --format esm && tsc --project tsconfig.build.json --noEmitOnError false",
    "prepublishOnly": "npm run build && npm run check"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "workflow",
    "agents"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fnnm/opencode-dynamic-workflows.git"
  },
  "author": "fnnm",
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.18",
    "@sinclair/typebox": "^0.34.49",
    "acorn": "^8.16.0"
  },
  "devDependencies": {
    "@biomejs/biome": "2.4.16",
    "@opencode-ai/sdk": "^1.14.18",
    "bun-types": "latest",
    "typescript": "latest"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.14.18"
  }
}

